//! Small shared helpers: quoting, doc comments, relative import paths.

use veld_codegen::naming::{self, Lang};
use veld_codegen::{CodeWriter, FileSet, GenDiagnostic};
use veld_ir::{Decl, Literal};

/// First line of every generated file.
pub const HEADER: &str = "// Code generated by veld. DO NOT EDIT.";

/// A single-quoted TypeScript string literal.
#[must_use]
pub fn ts_str(s: &str) -> String {
    let mut out = String::with_capacity(s.len() + 2);
    out.push('\'');
    for c in s.chars() {
        match c {
            '\\' => out.push_str("\\\\"),
            '\'' => out.push_str("\\'"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            c if (c as u32) < 0x20 => out.push_str(&format!("\\u{:04x}", c as u32)),
            c => out.push(c),
        }
    }
    out.push('\'');
    out
}

#[must_use]
pub fn is_ident(s: &str) -> bool {
    let mut chars = s.chars();
    chars
        .next()
        .is_some_and(|c| c.is_ascii_alphabetic() || c == '_' || c == '$')
        && chars.all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '$')
}

/// An object property key: bare when it is an identifier, quoted otherwise.
#[must_use]
pub fn prop_key(name: &str) -> String {
    if is_ident(name) {
        name.to_string()
    } else {
        ts_str(name)
    }
}

/// The TypeScript identifier of a declaration (reserved words and hazards escaped).
#[must_use]
pub fn type_name(d: &Decl) -> String {
    naming::escape_type(Lang::Ts, &d.name)
}

/// A JSON-compatible TypeScript literal for an IR literal (enum variants use the wire value).
#[must_use]
pub fn literal(l: &Literal) -> String {
    match l {
        Literal::String(s) => ts_str(s),
        Literal::Int(i) => i.to_string(),
        Literal::Float(f) => veld_codegen::canonical::es_number(*f),
        Literal::Bool(b) => b.to_string(),
        Literal::Null => "null".to_string(),
        Literal::EnumVariant { wire, .. } => ts_str(wire),
        Literal::EmptyList => "[]".to_string(),
    }
}

/// Writes a `/** ... */` block for docs and a deprecation notice, or nothing.
pub fn doc_comment(w: &mut CodeWriter, docs: Option<&str>, deprecated: Option<&str>) {
    let mut lines: Vec<String> = docs
        .map(|d| {
            d.trim()
                .lines()
                .map(|l| l.trim_end().replace("*/", "*\\/"))
                .collect()
        })
        .unwrap_or_default();
    if let Some(msg) = deprecated {
        let msg = msg.replace("*/", "*\\/");
        lines.push(if msg.is_empty() {
            "@deprecated".to_string()
        } else {
            format!("@deprecated {msg}")
        });
    }
    match lines.as_slice() {
        [] => {}
        [one] => {
            w.line(format!("/** {one} */"));
        }
        many => {
            w.line("/**");
            for l in many {
                w.line(if l.is_empty() {
                    " *".to_string()
                } else {
                    format!(" * {l}")
                });
            }
            w.line(" */");
        }
    }
}

/// Relative import specifier from the file `from_file` (with extension) to the module `to`
/// (root-relative, no extension).
#[must_use]
pub fn rel_import(from_file: &str, to: &str) -> String {
    let from_dir: Vec<&str> = {
        let mut parts: Vec<&str> = from_file.split('/').collect();
        parts.pop();
        parts
    };
    let to_parts: Vec<&str> = to.split('/').collect();
    let common = from_dir
        .iter()
        .zip(&to_parts)
        .take_while(|(a, b)| a == b)
        .count();
    let ups = from_dir.len() - common;
    let rest = to_parts[common..].join("/");
    if ups == 0 {
        format!("./{rest}")
    } else {
        format!("{}{rest}", "../".repeat(ups))
    }
}

/// Adds a generated file, mapping a path error to a generation diagnostic.
pub fn add_file(
    files: &mut FileSet,
    path: &str,
    content: String,
) -> Result<(), Vec<GenDiagnostic>> {
    files.add(path, content).map_err(|e| {
        vec![GenDiagnostic::new(
            "E0805",
            format!("cannot add generated file: {e}"),
        )]
    })
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn quotes_strings() {
        assert_eq!(ts_str("it's\n"), "'it\\'s\\n'");
    }

    #[test]
    fn relative_imports() {
        assert_eq!(rel_import("models/a.ts", "models/b"), "./b");
        assert_eq!(rel_import("models/a.ts", "runtime/veld"), "../runtime/veld");
        assert_eq!(rel_import("index.ts", "models/b"), "./models/b");
        assert_eq!(
            rel_import("clients/iam/models/a.ts", "runtime/veld"),
            "../../../runtime/veld"
        );
        assert_eq!(rel_import("a/b/c.ts", "a/x/y"), "../x/y");
    }

    #[test]
    fn doc_blocks() {
        let mut w = CodeWriter::new();
        doc_comment(&mut w, Some("One."), None);
        doc_comment(&mut w, Some("A\n\nB"), Some("use C"));
        assert_eq!(
            w.finish(),
            "/** One. */\n/**\n * A\n *\n * B\n * @deprecated use C\n */\n"
        );
    }
}
